        Put(Alpha(Text, 0x01), "FilesMate.TextControl.CaretHostBrush");
        Put(Alpha(Card, 0xF0), "FilesMate.AddressBar.BackgroundBrush");
        Put(Alpha(Dark ? Text : Card, Dark ? (byte)0x0F : (byte)0xB8), "FilesMate.Glass.SurfaceBrush");
        Put(Alpha(Dark ? Text : Card, Dark ? (byte)0x19 : (byte)0xDF), "FilesMate.Glass.SurfaceHoverBrush");
        Put(Alpha(Dark ? Text : Card, Dark ? (byte)0x1A : (byte)0x78), "FilesMate.Glass.CardBrush");
        Put(Alpha(Dark ? Text : Card, Dark ? (byte)0x17 : (byte)0x99), "FilesMate.Glass.HighlightBrush");
        Put(Alpha(Dark ? Text : Card, Dark ? (byte)0x10 : (byte)0x59), "FilesMate.Glass.SheenBrush", "FilesMate.LiquidGlass.InnerHighlightBrush");
        Put(Alpha(Dark ? Text : Card, Dark ? (byte)0x20 : (byte)0x62), "FilesMate.IconFrame.HighlightBrush");
        Put(Border, "FilesMate.IconFrame.BorderBrush", "FilesMate.LiquidGlass.BorderBrush");
        Put(Alpha(Card, 0), prefix + "Tab.BackgroundBrush");
        Put(Alpha(0xFF000000, Dark ? (byte)0x26 : (byte)0x1A), "FilesMate.SettingsOverlay.ScrimBrush");
        Put(Alpha(0xFF000000, 0x24), "FilesMate.LiquidGlass.ShadowBrush");
        Put(Light.Canvas, "FilesMate.ThemePreview.LightFill");
        Put(DarkSkin.Canvas, "FilesMate.ThemePreview.DarkFill");
        return colors;
    }

    public static uint Alpha(uint color, byte alpha) => (color & 0xFFFFFF) | ((uint)alpha << 24);
    public static uint Mix(uint color, uint background, double amount)
    {
        uint Channel(int shift) => (uint)Math.Round(((color >> shift) & 255) * amount + ((background >> shift) & 255) * (1 - amount));
        return 0xFF000000 | Channel(16) << 16 | Channel(8) << 8 | Channel(0);
    }
    private static double Contrast(uint first, uint second)
    {
        static double Luminance(uint color)
        {
            static double Linear(uint channel)
            {
                var value = channel / 255d;
                return value <= .04045 ? value / 12.92 : Math.Pow((value + .055) / 1.055, 2.4);
            }
            return .2126 * Linear((color >> 16) & 255) + .7152 * Linear((color >> 8) & 255) + .0722 * Linear(color & 255);
        }
        var a = Luminance(first);
        var b = Luminance(second);
        return (Math.Max(a, b) + .05) / (Math.Min(a, b) + .05);
    }
    public static double ContrastRatio(uint first, uint second) => Contrast(first, second);
    private static uint Lift(uint color, byte amount)
    {
        uint Channel(int shift) => Math.Min(255, ((color >> shift) & 255) + amount);
        return 0xFF000000 | Channel(16) << 16 | Channel(8) << 8 | Channel(0);
    }
    private static uint AccentLift(uint color, byte amount) => (color & 0xFF000000) | (Lift(color, amount) & 0xFFFFFF);
    private static uint Shade(uint color, double factor)
    {
        // Preserve the historical byte truncation and legacy custom-accent alpha.
        uint Channel(int shift) => (uint)(((color >> shift) & 255) * factor);
        return (color & 0xFF000000) | Channel(16) << 16 | Channel(8) << 8 | Channel(0);
    }
}
